import { DeleteObjectsCommand, GetObjectCommand, HeadObjectCommand, ListObjectsV2Command, PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { Injectable, Logger } from '@nestjs/common';
import type { Readable } from 'node:stream';

/**
 * This service's own bucket (S3_BUCKET = ac-returns) with credentials limited to it (MinIO user svc-returns).
 * Generated by `ac configure` / `ac k8s secrets` from the "objectStore": true flag in package.json.
 */
@Injectable()
export class ObjectStore {
  private readonly log = new Logger(ObjectStore.name);
  readonly bucket = process.env.S3_BUCKET ?? 'ac-returns';
  private readonly s3 = new S3Client({
    endpoint: process.env.S3_ENDPOINT,
    region: process.env.S3_REGION ?? 'us-east-1',
    forcePathStyle: true,
    credentials: { accessKeyId: process.env.S3_ACCESS_KEY ?? '', secretAccessKey: process.env.S3_SECRET_KEY ?? '' },
    requestHandler: { requestTimeout: 10_000, connectionTimeout: 3_000 },
  });

  get configured() {
    return Boolean(process.env.S3_ENDPOINT && process.env.S3_ACCESS_KEY && process.env.S3_SECRET_KEY);
  }

  async put(key: string, body: Buffer, contentType = 'image/webp') {
    await this.s3.send(new PutObjectCommand({ Bucket: this.bucket, Key: key, Body: body, ContentType: contentType, CacheControl: 'private, max-age=3600' }));
  }

  /** null when the object does not exist */
  async get(key: string): Promise<{ body: Readable; length?: number; type?: string } | null> {
    try {
      const r = await this.s3.send(new GetObjectCommand({ Bucket: this.bucket, Key: key }));
      return { body: r.Body as Readable, length: r.ContentLength, type: r.ContentType };
    } catch (e) {
      if ((e as { name?: string }).name === 'NoSuchKey') return null;
      throw e;
    }
  }

  async exists(key: string) {
    try {
      await this.s3.send(new HeadObjectCommand({ Bucket: this.bucket, Key: key }));
      return true;
    } catch {
      return false;
    }
  }

  async list(prefix: string): Promise<string[]> {
    const keys: string[] = [];
    let token: string | undefined;
    do {
      const r = await this.s3.send(new ListObjectsV2Command({ Bucket: this.bucket, Prefix: prefix, ContinuationToken: token }));
      keys.push(...(r.Contents ?? []).map((o) => o.Key!).filter(Boolean));
      token = r.IsTruncated ? r.NextContinuationToken : undefined;
    } while (token);
    return keys;
  }

  async deleteKeys(keys: string[]) {
    for (let i = 0; i < keys.length; i += 1000) {
      const chunk = keys.slice(i, i + 1000);
      if (chunk.length) await this.s3.send(new DeleteObjectsCommand({ Bucket: this.bucket, Delete: { Objects: chunk.map((Key) => ({ Key })), Quiet: true } }));
    }
  }

  /** best effort — a failed cleanup leaves unreachable objects, never broken pages */
  async deletePrefix(prefix: string) {
    try {
      await this.deleteKeys(await this.list(prefix));
    } catch (e) {
      this.log.warn(`cleanup of ${prefix} failed: ${(e as Error).message}`);
    }
  }
}
